X = np.column_stack(((DATA[:, 0] - 0.15) / 1.25,
                     (DATA[:, 1] - 0.12) / 0.88,
                     (DATA[:, 2] + 0.045) / 0.09))
MODEL = RBFInterpolator(X, DATA[:, 3], kernel="cubic",
                        smoothing=0.0, neighbors=24)


def _nominal(cock, power, shift):
    q = np.array([[(cock - 0.15) / 1.25,
                   (power - 0.12) / 0.88,
                   (shift + 0.045) / 0.09]])
    return float(MODEL(q)[0])


def predict(knobs: dict, visible: dict) -> list[float]:
    cock = float(knobs["cock"])
    power = abs(float(knobs["power"]))
    shift = float(knobs["shift"])
    post_x = float(visible.get("stop_post.posx", -0.04))
    striker_z = float(visible.get("striker.posz", 0.71))

    # The lower inner striker corner meets the post's right face.
    a = striker_z - 0.620 + 0.014
    radius = np.hypot(a, 0.008)
    arg = np.clip((post_x + 0.020) / radius, -0.999999, 0.999999)
    theta = np.arctan2(0.008, a) + np.arcsin(arg)
    theta0 = -0.1162

    # Match motor plus spring work to an equivalent nominal-collision run.
    # k/G=0.16 is inherited world information and agrees with this instance's
    # early-swing traces. Account for the small striker-inertia change too.
    ratio = 0.16
    target = (power * (cock - theta)
              + 0.5 * ratio * ((cock + 0.3) ** 2 - (theta + 0.3) ** 2))
    inertia_nom = (0.00155 + 0.020 * 0.200**2
                   + 0.097 * (0.034**2 + (0.080 + shift)**2))
    inertia_new = inertia_nom + 0.026 * ((striker_z - 0.620)**2 - 0.090**2)
    target *= inertia_nom / inertia_new
    v0 = theta0 + 0.3
    cterm = target + power * v0 + 0.5 * ratio * v0 * v0
    u = (-power + np.sqrt(max(0.0, power * power + 2 * ratio * cterm))) / ratio
    equivalent_cock = float(np.clip(u - 0.3, 0.10, 1.50))
    landing = _nominal(equivalent_cock, power, shift)

    # Decode the nominal range as a tangential launch speed and recompute
    # flight at the changed stop angle. Very long throws are in the observed
    # post-penetration mode, where this contact-angle model is inapplicable.
    if abs(theta - theta0) > 1e-6 and landing > -6.0:
        r = 0.200
        g = 9.81
        x0 = r * np.sin(theta0)
        h0 = 0.620 + r * np.cos(theta0) - 0.016
        travel = x0 - landing
        aa = travel / (r * np.cos(theta0))
        denom = h0 + r * np.sin(theta0) * aa
        if denom > 0.03:
            omega = np.sqrt(0.5 * g * aa * aa / denom)
            x1 = r * np.sin(theta)
            h1 = 0.620 + r * np.cos(theta) - 0.016
            vx = -r * omega * np.cos(theta)
            vz = r * omega * np.sin(theta)
            flight = (vz + np.sqrt(vz * vz + 2 * g * h1)) / g
            landing = x1 + vx * flight

    return [float(landing)]
